package com.vidyavedika.admin_service.entity; import jakarta.persistence.*; import java.time.*; @Entity @Table(name="audit_logs") public class AuditLog {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; Long actorUserId; String action; String resource; String detail; LocalDateTime createdAt; @PrePersist void init(){createdAt=LocalDateTime.now();} public Long getId(){return id;} public Long getActorUserId(){return actorUserId;} public void setActorUserId(Long v){actorUserId=v;} public String getAction(){return action;} public void setAction(String v){action=v;} public String getResource(){return resource;} public void setResource(String v){resource=v;} public String getDetail(){return detail;} public void setDetail(String v){detail=v;} public LocalDateTime getCreatedAt(){return createdAt;}}
